chart.setPosition('A8','F19');
chart.title.text = 'Revenue by product';

const file = await SpreadsheetFile.exportXlsx(workbook);
await file.save('sales.xlsx');
const image = await workbook.render({sheetName:'Sales',range:'A1:F19',scale:1.5});

